#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){if(argc!=3)return 1;int n,k;ifstream f(argv[1]);f>>n>>k;if(k>12)return 2;vector<int> gen(3*n);for(int &a:gen)f>>a;if(!f)return 3;int N=1<<(2*k);vector<unsigned char>d(N,255),pg(N,255);vector<int> pred(N,-1),queue;d[0]=0;queue.push_back(0);for(size_t i=0;i<queue.size();i++){int a=queue[i];for(int j=0;j<(int)gen.size();j++){int b=a^gen[j];if(d[b]==255){d[b]=d[a]+1;pred[b]=a;pg[b]=j;queue.push_back(b);}}}if((int)queue.size()!=N)return 4;string p=argv[2];ofstream g(p+"_distance.bin",ios::binary),h(p+"_pred.bin",ios::binary),z(p+"_generator.bin",ios::binary);g.write((char*)d.data(),N);h.write((char*)pred.data(),4*N);z.write((char*)pg.data(),N);map<int,int>hist;for(auto a:d)hist[a]++;for(auto [a,b]:hist)cout<<a<<' '<<b<<'\n';}
